INSERT INTO `products` VALUES ('P00728','Joy Skin Fruits Fruit Moisturizing Skin Cream','Radiant Skin','moisturizer',350.00,399.00,2,1.0,0,'data:image/jpeg;base64,','This is a widely popular, deep-nourishing daily cold cream designed for all skin types. Enriched with natural Apple extracts, Jojoba oil, and Almond oil, it claims to deliver up to 48 hours of intense moisture retention. Its fast-absorbing, non-sticky formula creates a protective barrier over the skin against extreme dryness and environmental pollution, leaving your complexion soft, velvety smooth, and naturally radiant.','2026-10-03 12:43:20'),('P02244','inatur Hydrating Rose Water Toner','Radiant Skin','toner',199.00,250.00,2,5.0,2,'data:image/jpeg;base64,','This is a 100% natural, alcohol-free hydrating facial toner and mist formulated to accommodate normal, dry, and sensitive skin types. Carefully enriched with botanical active ingredients like Pure Rose water, Aloe Vera, Calendula, and Geranium, it acts to quickly restore your skin\'s natural pH balance right after face washing. Its calming formula tightens open pores, reduces skin inflammation or redness, and supplies instant multi-depth hydration to leave your face feeling soft, refreshed, and looking naturally glowing.','2026-10-04 11:10:02'),('P05095','Orrypure Night Cream for Brightening & Nourishing.','Radiant Skin','nightcream',189.00,200.00,2,1.0,0,'data:image/jpeg;base64,','This is an organic, paraben-free anti-aging and skin-brightening night cream formulated for all skin types. It targets common skin issues by fading dark spots, reducing acne breakouts, combating dullness, and smoothing early fine lines. Its moisturizing formula helps deeply hydrate and repair the skin barrier overnight to leave behind a fresh, soft, and radiant complexion by morning.','2026-10-03 17:41:45'),('P05982','Arvelon Advanced Glow Cream.','Radiant Skin','nightcream',390.00,540.00,2,1.0,0,'data:image/jpeg;base64,','This is a high-performance skin-brightening and deep moisturizing face cream. Formulated with potent active ingredients like Alpha Arbutin, Kojic Acid, Niacinamide, and Hyaluronic Acid, it targets hyperpigmentation, stubborn melasma, age spots, and uneven skin tone. It provides intense hydration while refining large skin pores to leave behind a smooth, plump, and youthful glowing complexion.','2026-10-04 10:40:06'),('P06846','JiViSa Ananta Drench Hydrating Facial Cleanser','Radiant Skin','cleanser',399.00,499.00,2,1.0,0,'data:image/jpeg;base64,','It is a gentle , sulfate-free hydrating face wash formulated primarily for dry, sensitive, and easily irritated skin types. It is enriched with Ayurvedic ingredients like kumkumadi oil and jatamansi which help deeply cleanse the skin without stripping away its natural oils or leaving that tight, dry feeling after washing.','2026-10-03 11:26:46'),('P06894','Simple Skincare','Radiant Skin','cleanser',450.00,550.00,2,1.0,0,'data:image/jpeg;base64,','soap - Free Gel Formula , Skin - Loving Ingredients ,Clean Skincare Philosophy Benefits to skincare .','2026-10-03 07:51:46'),('P08860','Ayumcure 1% Hyaluronic Sunscreen Gel (SPF 50 PA++++ ).','Radiant Skin','sunscreen',445.00,488.00,2,1.0,0,'data:image/jpeg;base64,','This is an ultra-lightweight, broad-spectrum gel sunscreen designed to provide 4-layer advanced protection against harmful UVA/UVB rays and blue light damage from screens. Enriched with 1% Hyaluronic Acid, Vitamin E, and Aloe Vera, it deeply hydrates, plumps, and calms sun-exposed skin while improving texture. Its non-greasy, fast-absorbing formula leaves no white cast, making it comfortable for daily indoor and outdoor wear across all skin types.','2026-10-03 13:25:08'),('P09647','ESPA Optimal Skin Pro - Serum','Radiant Skin','serum',779.00,899.00,2,1.0,0,'data:image/jpeg;base64,','This is an intensely nourishing , nutrient - rich daily gel face serum designed to caltivate natural radiance. Skincare benefits include : Deep Hydration & Nourishment , Barrier Enhancement , Skin Brightening & Smoothing , Texture .','2026-10-03 06:43:29'),('P11721',': SKIOM Moisture Guard Cream.','Radiant Skin','moisturizer',699.00,867.00,2,1.0,0,'data:image/jpeg;base64,','This is a science-backed skin barrier repair moisturizer formulated with a specialized Tri-Biotic Complex (a blend of prebiotics, probiotics, and postbiotics) and ceramide-boosting actives. It is clinically proven to provide up to 72 hours of continuous hydration and repair barrier micro-cracks. Enriched with calming botanical ingredients like Beta Glucan and Centella Asiatica, its lightweight, non-greasy formula reduces redness and irritation, making it excellent for dry, sensitive, or heat-stressed skin','2026-10-03 12:45:11'),('P12914','L\'Occitane Immortelle Reset serum','Radiant Skin','serum',597.00,700.00,2,1.0,0,'data:image/jpeg;base64,','Capsule Suspension serum. A lightweight , hydrating face gel filled with suspended micro - pearls. When pumped , these beads rupture to deliver fresh nutrients that deeply hydrate the skin, smooth out its texture , and leave a radiant , dewy glow.','2026-10-03 07:30:12'),('P14657','Fixderma Cosmetic Laboratories (FCL) Balancing Face Toner.','Radiant Skin','toner',600.00,750.00,2,1.0,0,'data:image/jpeg;base64,','This is a gentle, dermatologist-tested pore-minimizing and exfoliating face toner developed with an ideal pH 5.0 to balance all skin types. Infused with active premium ingredients like Multifruit AHA, Witch Hazel Extract, Apple Amino Acid, and Rose Flower Extracts, it helps sweep away dead skin cells, clear deeply clogged impurities, and control excess facial oil production. Its soothing, non-drying formula reduces skin inflammation while preparing your skin barrier to better absorb subsequent treatments.','2026-10-04 11:03:34'),('P14989','Himalaya Purifying Neem Face Wash','Radiant Skin','cleanser',120.00,160.00,2,1.0,0,'data:image/jpeg;base64,','It is a highly popular, soap-free herbal formulation designed to clear extra oil, impurities, and deep-seated dirt from the face. Infused with the natural benefits of neem and turmeric, it targets and eliminates pimple-causing bacteria to prevent acne breakouts.','2026-10-03 11:35:15'),('P16567','Avyya Essential Moisturizer with Sunblock SPF 50.','Radiant Skin','sunscreen',680.00,999.00,2,1.0,0,'data:image/jpeg;base64,','This is a plant-derived, 2-in-1 daily lightweight sunscreen and hydrating moisturizer. It is carefully enriched with powerful ingredients like Ginseng, Niacinamide, Rice Water, and Squalane. It delivers multi-depth hydration while providing reliable broad-spectrum protection against skin tanning, sunburn, and UV damage. The formula is non-greasy, absorbs quickly, leaves no white cast, and dries down to a comfortable bright/matte finish that is suitable for all skin types.','2026-10-03 13:11:56'),('P21872','Flânerie Jasmine Sunset Rose Quartz Restorative Face & Eye Night Cream.','Radiant Skin','nightcream',690.00,880.00,2,1.0,0,'data:image/jpeg;base64,','This is a premium, 100% vegan 2-in-1 nighttime face and eye cream designed to deeply replenish, nourish, and rejuvenate the skin\'s complexion while you sleep. Infused with Rose Quartz and Jasmine flower extract, it aims to gently buff away dead cells, clear surface impurities, and lock in long-lasting moisture. Its high-performance formula works to smooth out fine lines, decrease under-eye puffiness, and brighten a dull complexion without feeling excessively greasy or heavy.','2026-10-04 10:43:41'),('P22053','Zordan Herbals Rose Skin Toner.','Radiant Skin','toner',100.00,125.00,2,1.0,0,'data:image/jpeg;base64,','This is a gentle, aromatherapy-based herbal face toner spray formulated to benefit all skin types. Infused with natural rose petal extracts, it sweeps away leftover dirt, environmental pollutants, and makeup residue post-wash. Its pH-balanced formula locks in long-lasting moisture, soothes initial skin redness, controls excess facial oils, and firms the appearance of large skin pores to reveal a soft, refreshed, and naturally glowing complexion.','2026-10-04 11:05:22'),('P24639','Earthraga Hydrating Sunscreen','Radiant Skin','sunscreen',289.00,349.00,2,1.0,0,'data:image/jpeg;base64,','This is a clean, natural broad-spectrum sunscreen formulated to protect all skin types from harmful UVA and UVB rays. Enriched with skin-loving organic ingredients like Green Tea extract, Licorice extract, and Cucumber, it cools down skin inflammation while preventing sun tanning and premature aging. Its ultra-lightweight, non-greasy formula absorbs instantly without leaving behind a heavy white cast or clogging pores.','2026-10-03 13:22:04'),('P25532','Fami UK Refreshing Sunscreen','Radiant Skin','sunscreen',699.00,790.00,2,1.0,0,'data:image/jpeg;base64,','This is an ultra-resistant, broad-spectrum daily face sunscreen developed to shield all skin types from harmful UVA, UVB, and infrared rays. It features a lightweight, non-greasy fluid texture that absorbs quickly and leaves no white cast or sticky residue. It is waterproof and sweat-resistant, preventing premature sun-related aging and skin damage even during extreme heat and humidity.','2026-10-03 13:32:05'),('P27025','Sri Sri Tattva Rejuvenating Night Cream.','Radiant Skin','nightcream',199.00,225.00,2,1.0,0,'data:image/jpeg;base64,','This is an Ayurvedic, daily night repair moisturizer formulated to satisfy all skin types. Carefully enriched with natural botanical active ingredients like Aloe Vera, Cucumber, and Lime extracts, it targets environmental skin damage, repairs skin micro-cracks overnight, and restores lost moisture while you sleep. Its lightweight, non-greasy formula absorbs quickly into the skin to leave behind a soft, deeply hydrated, and refreshed complexion by morning.','2026-10-03 17:10:27'),('P27815','Uncommon Beauty Deep Hydration Serum','Radiant Skin','serum',698.00,892.00,2,1.0,0,'data:image/jpeg;base64,','This is an intensive , lipid - restoring daily treatment designed to deliver lasting moisture. Immediate  & Long Hydration , Plumping & Softening , Clean & Lightweight Formula.','2026-10-03 06:17:07'),('P27890','Kérastase Elixir Ultime Le Fondant Conditioner','Radiant Skin','cleanser',899.00,999.00,2,3.0,1,'data:image/jpeg;base64,','Kérastase Elixir Ultime Le Fondant Conditioner is a premium oil-infused hair conditioner. Here is the short description:\n• Main Purpose: Instantly delivers deep nourishment and intense shine to dull, dry hair.\n• Key Benefits: Softens the hair, helps in easy detangling, and controls frizz without weighing down your natural hair volume.\n• Hair Type: Best suited for fine to normal hair types.','2026-10-03 11:48:47'),('P28300','Ela de pure vitamin c serum','Radiant Skin','serum',389.00,499.00,2,1.0,0,'data:image/jpeg;base64,','A topical face serum formulated for skincare. based on standard formulation of this product, its key feature include:\nskin brightening , hydration , texture improvement.','2026-10-03 05:52:08'),('P29540','Good Vibes Ubtan De-Tan Glow Light Day Cream.','Radiant Skin','moisturizer',190.00,250.00,2,1.0,0,'data:image/jpeg;base64,','• This is a lightweight, non-greasy day moisturizer infused with traditional Ayurvedic ingredients like Turmeric and Saffron. Formulated with the power of serum and SPF 30 protection, it helps target stubborn tan lines, reduces pigmentation, and deeply hydrates the skin. It absorbs quickly to leave behind a smooth, healthy, and radiant complexion.','2026-10-03 12:23:49'),('P29564','Mamaearth Beetroot Hydraful Light Moisturizing Cream','Radiant Skin','moisturizer',220.00,399.00,2,1.0,0,'data:image/jpeg;base64,','This is a versatile, lightweight, and non-greasy daily moisturizing cream formulated to suit all skin types. Infused with natural Beetroot extracts and Hyaluronic Acid, it provides intense multi-depth hydration that lasts up to 24 hours. It actively banishes flakiness and dryness from the skin while promoting a healthy, natural pink glow. The fast-absorbing formula makes it an all-rounder cream that is suitable for application on the face, hands, and body.','2026-10-03 12:58:49'),('P30045','L - Glutathione','Radiant Skin','cleanser',299.00,399.00,2,1.0,0,'data:image/jpeg;base64,','Key Active Ingredients powered by an advanced blend of L - Glutathione. It also incorporates botanical additions like Liquorice Extract , Witch Hazel Extract , and Glycolic Acid.','2026-10-03 08:00:30'),('P31861','The Health Healer Night Cream (Bright | White | Clear Skin).','Radiant Skin','nightcream',300.00,540.00,2,1.0,0,'data:image/jpeg;base64,','This is an intensive skin brightening night cream formulated to be suitable for all skin types. Enriched with skin-nourishing ingredients like Vitamin E, Vitamin B3 (Niacinamide), and Jojoba Oil, it works overnight to provide deep hydration, target uneven skin tone, and fade dark spots. Its lightweight, paraben-free formula helps support the skin\'s natural repair cycle while you sleep without feeling heavy or sticky.','2026-10-03 17:15:31'),('P32327','mCaffeine Anti-Ageing Night Cream with Black Tea Complex.','Radiant Skin','moisturizer',399.00,449.00,2,1.0,0,'data:image/jpeg;base64,','This is a lightweight, non-sticky anti-aging night cream designed to restore and rejuvenate skin while you sleep. Powered by a specialized Black Tea Complex, Vegan Collagen Peptides, and Hyaluronic Acid, it targets visible signs of aging by minimizing fine lines and wrinkles. It claims to boost skin\'s natural collagen production by up to 80%, improving overall firmness, texture, and hydration without leaving a greasy layer.','2026-10-03 13:03:52'),('P40531','SKKIN Cosmetics Skin Toner Combo (Rose & Cucumber).','Radiant Skin','toner',168.00,248.00,2,1.0,0,'data:image/jpeg;base64,','This is a daily hydrating and skin-refreshing facial toner combo designed for all skin types.\n\\t• Rose Skin Toner (Pink Bottle): Enriched with natural rose extracts, it acts to gently cleanse, tone, and lock in hydration while balancing the skin\'s natural pH level after face washing.\n\\t• Cucumber Skin Toner (Green Bottle): Infused with cooling cucumber active extracts, it provides immediate soothing relief, helps refine the appearance of large skin pores, and sweeps away residual dirt or excess facial oils without over-drying.','2026-10-04 10:52:20'),('P40837','Little Extra Rice Berry Hydrating Face Wash','Radiant Skin','cleanser',324.00,449.00,2,1.0,0,'data:image/jpeg;base64,','• Main Purpose: Cleanses away dirt, daily impurities, and excess oil without stripping the skin\'s moisture.\n• Key Benefits: Promotes skin brightening, reduces dark spots, controls excess oil, and leaves skin plump and hydrated.\n• Skin Type: Safe and formulated for all skin types, including sensitive skin.','2026-10-03 12:07:20'),('P43209','Azafran Organics Skin Brightening face wash','Radiant Skin','cleanser',275.00,330.00,2,1.0,0,'data:image/jpeg;base64,','Formulated with Organic Licorice Extract and a multi - fruit botanical blend containing natural Alpha Hydroxy Acids from Bilberry , Sugar Cane , Orange , Lemon , and Sugar Maple.','2026-10-03 08:07:23'),('P43801','Ghar Soaps Magic Face Wash','Radiant Skin','cleanser',249.00,333.00,2,1.0,0,'data:image/jpeg;base64,','Key Ingredients: It is an Ayurveda-inspired skincare formulation powered by Saffron, Glutathione, and Encapsulated Lactic Acid beads. The active beads dissolve upon rubbing to exfoliate dead skin cells gently.','2026-10-03 11:42:23'),('P44067','Oshea Herbals Teatreefresh Balancing Skin Toner.','Radiant Skin','toner',220.00,276.00,2,1.0,0,'data:image/jpeg;base64,','This is a gentle, paraben-free oil-control face toner formulated primarily for normal, oily, and acne-prone skin types. Infused with Tea Tree oil, Neem extract, and Aloe Vera, it works effectively to restore your skin\'s natural pH balance and reduce excess sebum production. Its purifying formula helps eliminate acne-causing bacteria to minimize frequent breakouts and clear clogged pores, leaving the skin refreshed and hydrated without feeling greasy.','2026-10-04 11:07:24'),('P44722','Clarins Extra-Firming Nuit Wrinkle-Smoothing Revitalizing Night Cream for Dry Skin.','Radiant Skin','nightcream',850.00,900.00,2,1.0,0,'data:image/jpeg;base64,','This is a luxury, high-performance anti-aging night cream specially formulated to nourish and revitalize dry, loss-of-firmness skin types. Powered by Clarins\' advanced [COLLAGEN]³ Technology—a rich blend of collagen polypeptide, pecan extract, and mitracarpus extract—it targets collagen reserves to improve skin elasticity. Infused with youth-boosting Niacinamide and avocado peptides, it works intensely overnight to lift facial contours, plump up cheekbones, and visibly smooth out deep wrinkles while you sleep without leaving a greasy layer.','2026-10-03 17:37:24'),('P45890','The Skin Set 1% Retinol Night Cream.','Radiant Skin','nightcream',299.00,450.00,2,1.0,0,'data:image/jpeg;base64,','This is an advanced anti-aging overnight face cream designed to boost the skin\'s natural renewal process while you sleep. Formulated with a potent 1% Retinol concentration, it actively works to boost collagen and elastin synthesis. It targets visible signs of aging by reducing fine lines, smoothing wrinkles, and correcting uneven skin tone to restore a firm, plump, and youthful complexion.','2026-10-03 17:12:25'),('P45994','Ageless Total Anti - Aging serum','Radiant Skin','serum',599.00,700.00,2,1.0,0,'data:image/jpeg;base64,','A Concentrated , profession - grade corrective and resurfacing face serum design to address advanced sign of again its key benefits Exfoliation & Brightening , Wrinkle and Line Reduction , Antioxidant Protection.','2026-10-03 06:05:46'),('P47964','Lakmé Absolute Perfect Radiance Skin Brightening Light Crème.','Radiant Skin','nightcream',486.00,576.00,2,1.0,0,'data:image/webp;base64,','This is a popular, premium skin-brightening day cream formulated to fit all skin types. Infused with Niacinamide (Vitamin B3), Vitamin E, Vitamin C, and precious micro-crystals, it acts to gently polish the skin cell layers while noticeably evening out hyperpigmentation and tanning. Its moisture-rich yet ultra-lightweight formula melts into the skin smoothly with a silky feel, and it is built with SPF 20 to 30 PA++ to ensure reliable protection against daytime environmental sun damage.','2026-10-03 17:27:28'),('P53203','Oshea Herbals UV Shield Sun Block Formula','Radiant Skin','sunscreen',389.00,500.00,2,1.0,0,'data:image/jpeg;base64,','This is a popular broad-spectrum sunscreen cream formulated to shield all skin types from harmful UVA, UVB, and HEV (blue light) rays. Enriched with natural botanical actives like Papaya, Green Tea, and Liquorice extracts, it targets hyperpigmentation, reduces tanning, and prevents premature skin aging. Its lightweight, water-resistant, and non-greasy formula absorbs quickly into the skin without leaving behind a heavy white cast.','2026-10-03 13:19:13'),('P53564','Deconstruct Gel Sunscreen','Radiant Skin','sunscreen',419.00,514.00,2,1.0,0,'data:image/jpeg;base64,','This is a highly popular, 100% photostable gel sunscreen formulated specifically for oily, combination, and acne-prone skin types. Powered by 4 new-generation UV filters (MBBT, DHHB, BEMT, EHT), it provides long-lasting broad-spectrum defense against harmful UVA and UVB rays to prevent tanning and sun damage. Its incredibly lightweight, water-resistant gel formula absorbs quickly into the skin without leaving any greasy residue or white cast, while providing all-day oil control.','2026-10-03 13:15:53'),('P55231','HERA','Radiant Skin','serum',387.00,499.00,2,1.0,0,'data:image/jpeg;base64,','This is a highly concentrated , top - cellular anti - again serum engineered to revive again or mature skin.','2026-10-03 06:35:55'),('P57549','Dr. Sheth\'s Haldi & Hyaluronic Acid Sunscreen (SPF 50+ PA+++).','Radiant Skin','sunscreen',375.00,425.00,2,1.0,0,'data:image/jpeg;base64,','This is a highly popular, lightweight hybrid sunscreen specially formulated for Indian skin types. Infused with 1% Hyaluronic Acid for deep hydration and 1% Turmeric (Haldi) extract for its bright-looking, anti-inflammatory benefits, it repairs the skin barrier while shielding it from harmful UVA/UVB rays and blue light damage. Its non-greasy, gel-cream formula absorbs smoothly into the skin, leaving behind no white cast and giving a healthy, dewy finish.','2026-10-03 13:27:37'),('P60729','Caldera + Lab The Hydro Layer Anti-Aging Lightweight Moisturizer.','Radiant Skin','moisturizer',780.00,880.00,2,1.0,0,'data:image/jpeg;base64,','This is a premium, high-performance lightweight gel-cream moisturizer engineered specifically for men\'s skin. Powered by their proprietary B³OS+™ complex and biomimetic exosomes, it claims to deliver intense multi-depth hydration without leaving a greasy residue. It targets fine lines, wrinkles, and open pores while actively strengthening the skin barrier to promote a smooth, youthful complexion.','2026-10-03 12:56:00'),('P62645','mCaffeine Naked & Raw Coffee Face Wash','Radiant Skin','cleanser',284.00,349.00,2,1.0,0,'data:image/jpeg;base64,','• Main Purpose: Effectively removes dirt, stubborn tan, pollution, and excess oil from the skin.\n• Key Benefits: Deeply purifies pores, reduces puffiness, and restores a fresh, natural glow without drying the skin.\n• Skin Type: Best suited for normal to oily skin types.','2026-10-03 12:02:42'),('P63767','Poko Ultra Hydrating Moisturiser','Radiant Skin','moisturizer',788.00,900.00,2,1.0,0,'data:image/jpeg;base64,','This is a premium, plant-based botanical moisturizer formulated to deliver deep hydration and lock in moisture. It is specifically blended to revitalize dull, dry, or dehydrated skin types to promote a natural, healthy radiance. It absorbs effectively to condition the skin barrier without clogging pores.','2026-10-03 12:19:23'),('P66403','Personal Touch Skincare Skin Dam Crème Milky Skin Toner & Mist 2-in-1.','Radiant Skin','toner',399.00,451.00,2,1.0,0,'data:image/jpeg;base64,','This is a revolutionary dual-action milky skin toner, mist, and makeup primer designed to support oily, dry, and combination skin types. Powered by Squalane, Meadowfoam Seed Oil, and Argan Seed Oil, it blends the deep nourishment of a rich cream with the lightweight feel of a fluid mist. Its specialized Nano Emulsion Technology breaks down active lipids for quick absorption without leaving any greasy residue. It targets flaky, dehydrated surfaces and repairs cracks in a damaged skin barrier, ensuring up to 72 hours of intense moisture lock.','2026-10-04 10:59:26'),('P66861','Skin Fx Superfood Restoring Night Cream (Coffee + Ceramides).','Radiant Skin','nightcream',559.00,629.00,2,1.0,0,'data:image/jpeg;base64,','This is a 3-in-1 action barrier-boosting night moisturizer formulated primarily for oily, combination, and sensitive skin types. Enriched with active ingredients like Coffee extracts, Ceramides, and Gotu Kola, it functions to firm the skin, reduce fine lines, and deeply lock in moisture overnight. Its lightweight formula repairs micro-cracks in the skin barrier while you sleep, promoting a healthy and glowing complexion by morning.','2026-10-03 17:32:46'),('P70853','Fresh Rose Deep Hydration Face Cream.','Radiant Skin','moisturizer',650.00,760.00,2,1.0,0,'data:image/jpeg;base64,','This is a luxury, barrier-boosting gel-cream moisturizer developed primarily for normal to dry skin types. Infused with real Damask rose extract, rosewater, and a duo of hyaluronic acids, it utilizes advanced time-release hydropatches to deliver up to 72 hours of intense, continuous hydration. The lightweight formula strengthens the skin’s natural barrier while leaving a soft, smooth, and petal-dewy finish.','2026-10-03 13:01:10'),('P73350','Garnier','Radiant Skin','serum',250.00,299.00,2,1.0,0,'data:image/jpeg;base64,','explore different types of serums for face','2026-10-03 05:39:33'),('P75002','Swiss Beauty 24k Gold Skin Care Serum','Radiant Skin','serum',499.00,597.00,2,1.0,0,'data:image/jpeg;base64,','This is a lightweight , water - based face serum infused with gold flakes designed to promote a youthful complexion.','2026-10-03 06:09:35'),('P78762','Ela De Pure','Radiant Skin','cleanser',745.00,899.00,2,1.0,0,'data:image/jpeg;base64,','Soothing Hydration formulated with high - grade Aloe Vera leaf juice to instantly calm irritated skin , soothe redness , and ensure your face feels soft and refreshed post - wash.','2026-10-03 08:11:18'),('P80514','Lashika Premium Care Mineral Sunscreen','Radiant Skin','sunscreen',270.00,327.00,2,1.0,0,'data:image/jpeg;base64,','This is a physical or mineral-based sunscreen designed for all skin types, including sensitive and acne-prone skin. Powered by natural UV filters like Zinc Oxide and Titanium Dioxide, it reflects harmful UVA and UVB rays to protect against tanning, sunburn, and premature aging. It features an oil-free, lightweight, non-greasy formula enriched with nourishing botanical ingredients like Aloe Vera, Vitamin E, Carrot Seed Oil, and Shea Butter to hydrate and soothe sun-exposed skin.','2026-10-03 13:08:00'),('P81059','Olivia Quido Clinical Skincare Balancing Toner (with Lilac and Sea Daffodil)','Radiant Skin','toner',790.00,900.00,2,1.0,0,'data:image/jpeg;base64,','This is a luxury, alcohol-free multi-benefit facial toner formulated to satisfy all skin types, from dry to oily. Infused with premium botanical actives like Lilac plant stem cells and Sea Daffodil extract, it targets excess oil, clears residual makeup, and tightens pores while restoring your skin\'s natural pH balance. The soothing formula hydrates and reduces surface redness to perfectly prep your skin for subsequent serum steps.','2026-10-04 10:54:41'),('P83143','Mock up / Placeholder Design Cream','Radiant Skin','moisturizer',340.00,499.00,2,4.0,1,'data:image/jpeg;base64,','As printed on the label template, it is conceptualized as an Intense Hydration with Antioxidant-Rich face cream. It comes in a 30 ml (1 fl. oz.) size and is designed to represent a hypothetical daily skincare formula that deeply moisturizes the skin while protecting it from free radical damage.','2026-10-03 12:49:43'),('P83710','Lakme','Radiant Skin','serum',498.00,559.00,2,1.0,0,'data:image/jpeg;base64,','This is a lightweight face serum designed for daily skincare routines. Its primary benefits and features include : Skin Brightening, Fast - Absorbing','2026-10-03 05:58:03'),('P86602','Seasonly Paris Serum TensioLift','Radiant Skin','serum',899.00,998.00,2,1.0,0,'data:image/jpeg;base64,','A high - performance firming and lifting face serum. Formulated with 10 %  Argireline to target expression lines by relaxing facial micro - contractions , combined with Matrixyl  to  boots natural collage production , pluming mature skin.','2026-10-03 06:31:26'),('P89626','Yuri Woori Bubble Anti-Aging Toner.','Radiant Skin','toner',598.00,850.00,2,1.0,0,'data:image/jpeg;base64,','This is a K-beauty inspired lightweight, cushiony foam-texture face toner formulated to satisfy all skin types. Powered by antioxidant-rich superfruits like Blueberry, Blackberry, and Acai berry, it targets early visible signs of aging by combating free radicals and smoothing fine lines. Infused with Niacinamide, it actively boosts skin elasticity, refines texture, and evens out overall skin tone to leave behind a plumper, healthier-looking complexion while prepping your skin to absorb subsequent serums or moisturizers.','2026-10-04 10:49:49'),('P90482','Minimalist Multi-Vitamin SPF 50 Sunscreen (Broad Spectrum PA++++ ).','Radiant Skin','sunscreen',325.00,399.00,2,1.0,0,'data:image/jpeg;base64,','This is a highly rated, lightweight, moisturizer-meets-sunscreen formulation designed to satisfy all skin types. Infused with Niacinamide (Vitamin B3), Vitamin B5, Vitamin E, and Vitamin F, it actively strengthens the skin barrier, reduces photoaging, and repairs skin damage caused by extreme UV exposure. Formulated with four highly photostable modern UV filters, it ensures high broad-spectrum shield defense and completely disappears upon application, leaving no white cast and a natural, non-shiny finish.','2026-10-03 13:29:50'),('P93758','Peau Skincare Moisturizer Cream.','Radiant Skin','moisturizer',249.00,300.00,2,1.0,0,'data:image/jpeg;base64,','This is a lightweight, non-oily daily moisturizing cream formulated to suit all skin types. It focuses on providing intense hydration and locking in long-lasting moisture to promote soft, smooth, and radiant skin. Its fast-absorbing formula strengthens the skin barrier without leaving a heavy or greasy residue.','2026-10-03 12:21:33'),('P94204','Ningen Vitamin C Facial Toner','Radiant Skin','toner',299.00,398.00,2,1.0,0,'data:image/jpeg;base64,','This is a gentle, alcohol-free skin-brightening facial toner mist formulated to suit all skin types. Infused with 0.5% Magnesium Ascorbyl Phosphate (a stable and gentle derivative of Vitamin C) and nourishing Aloe Vera extracts, it targets hyperpigmentation, uneven skin tone, and stubborn dark spots. Its lightweight, fast-absorbing formula sweeps away residual impurities, purifies facial pores, and loads the cells with antioxidant protection to leave your skin feeling soft, hydrated, and naturally radiant.','2026-10-04 11:01:34'),('P96172','Generic Brand Body Lotion','Radiant Skin','sunscreen',470.00,500.00,2,1.0,0,'data:image/jpeg;base64,','• As printed on the package template, it is a generic concept for a Body Lotion. It indicates a fluid volume of 100 ml (3.4 fl. oz.) and features a metallic violet tube body with a gold-tone flip-top cap, designed to represent a luxury or premium cosmetic product mockup for presentation purposes.\nIf','2026-10-03 13:34:56'),('P96530','Umrao Skincare Day & Night Cream.','Radiant Skin','nightcream',600.00,726.00,2,1.0,0,'data:image/jpeg;base64,','This is a comprehensive all-day hydration moisturizer formulated for all skin types. Carefully enriched with Hyaluronic Acid, Ceramides, Aloe Vera, and Vitamin E, it provides intense multi-depth hydration and boosts natural skin elasticity. The lightweight, non-greasy formula acts to prep and shield the skin during the daytime, while deeply nourishing and supporting structural skin barrier repair overnight.','2026-10-04 10:46:36'),('P98627','HIEMY Ceramide Face Toner.','Radiant Skin','toner',299.00,399.00,2,1.0,0,'data:image/jpeg;base64,','This is a skin-barrier strengthening hydrating daily face toner designed to provide deep hydration. Enriched with structural Ceramides, Niacinamide, and Hyaluronic Acid, it targets a compromised skin barrier by sealing in deep-layer moisture loops and locking out environmental dirt. Its lightweight, fast-absorbing formula prevents moisture loss and immediately soothes dry, sensitive, or irritated skin flakes without leaving a heavy residue.','2026-10-04 10:56:38');
